SELECT (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_listing' AND table_name='listing_info' AND column_name IN ('owner_customer_id','community_name','district_code','asking_price_yuan','version'))=5 AND (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_listing' AND table_name='listing_asset' AND column_name IN ('id','listing_id','asset_type','storage_key','visibility','sort_order','status','created_by','created_at','updated_at','deleted'))=11 AND (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_listing' AND table_name='listing_private_info' AND column_name IN ('listing_id','certificate_no_ciphertext','certificate_key_id','created_at','updated_at'))=5 AND (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_listing' AND table_name='listing_price_record' AND column_name IN ('id','listing_id','old_price_yuan','new_price_yuan','reason','operator_user_id','request_id','created_at'))=8 AND (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_listing' AND table_name='listing_status_record' AND column_name IN ('id','listing_id','from_status','to_status','action','reason','operator_user_id','request_id','created_at'))=9 AND (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_listing' AND table_name='listing_command_receipt' AND column_name IN ('actor_user_id','operation','request_id','request_hash','listing_id','status','created_at'))=7 AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='bk_listing' AND table_name IN ('listing_asset','listing_private_info','listing_price_record','listing_status_record','listing_command_receipt') AND engine='InnoDB')=5;
